+.tag{
+  display:inline-flex;
+  align-items:center;
+  gap:8px;
+  color:var(--muted);
+  font-size:.95rem;
+}
+
+.book-link{
+  margin-top:auto;
+  display:inline-flex;
+  color:var(--text);
+  font-weight:700;
+  letter-spacing:.02em;
+}
+.book-link:hover{color:var(--red)}
+
+.hidden{display:none !important}
+
+/* FAQ */
+.accordion{display:grid; gap:10px}
+.acc-item{
+  border:1px solid rgba(255,255,255,.10);
+  background:rgba(255,255,255,.04);
+  border-radius:var(--radius);
+  overflow:hidden;
+}
+.acc-btn{
+  width:100%;
+  text-align:left;
+  padding:16px 18px;
+  border:0;
+  background:transparent;
+  color:var(--text);
+  cursor:pointer;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:12px;
+}
+.acc-btn strong{font-family:Oswald, sans-serif; text-transform:uppercase; letter-spacing:.04em; font-size:1.08rem}
+.acc-btn .icon{color:var(--muted)}
+.acc-panel{padding:0 18px 16px; color:var(--muted)}
+.acc-panel[hidden]{display:none}
+
+/* Newsletter */
+.form{
+  display:flex;
+  gap:10px;
+  flex-wrap:wrap;
+  align-items:flex-start;
+}
+.field{flex:1; min-width:220px}
+.input{
+  width:100%;
+  padding:12px 14px;
+  border-radius:12px;
+  border:1px solid rgba(255,255,255,.14);
+  background:rgba(255,255,255,.04);
+  color:var(--text);
+  outline:none;
+}
+.input:focus{border-color:rgba(230,57,70,.55); box-shadow:0 0 0 4px rgba(230,57,70,.14)}
+.help{margin-top:8px; font-size:.92rem; color:var(--muted)}
+.help.error{color:#ffb4b9}
+.help.success{color:#9bf6b1}
+
+/* Footer */
+footer{padding:46px 0 26px; border-top:1px solid rgba(255,255,255,.08)}
+.footer-grid{display:grid; grid-template-columns: 2fr 1fr 1fr 1.2fr; gap:18px}
+@media (max-width: 920px){.footer-grid{grid-template-columns:1fr 1fr;}}
+@media (max-width: 560px){.footer-grid{grid-template-columns:1fr;}}
+
+.footer-col h4{
+  font-family:Oswald, sans-serif;
+  text-transform:uppercase;
+  letter-spacing:.08em;
+  font-size:1rem;
+  margin:0 0 10px;
+}
+.footer-col a{display:block; color:var(--muted); padding:6px 0}
+.footer-col a:hover{color:var(--text)}
+.footer-bottom{display:flex; justify-content:space-between; gap:12px; flex-wrap:wrap; align-items:center; margin-top:16px; color:var(--soft)}
+
+.country{
+  display:flex;
+  align-items:center;
+  gap:10px;
+}
+.country select{min-width:180px}
+
+/* Page header */
+.page-hero{
+  padding:62px 0 38px;
+}
+.crumb{color:var(--soft); text-transform:uppercase; letter-spacing:.12em; font-size:.78rem}
+
*** End Patch
