+    select?.addEventListener('change', apply);
+    apply();
+  }
+
+  // FAQ accordion (single open)
+  const accordion = document.querySelector('[data-accordion]');
+  if (accordion) {
+    const items = $$('[data-acc-item]', accordion);
+    const closeAll = () => {
