+    items.forEach((it) => {
+      const btn = $('[data-acc-btn]', it);
+      const panel = $('[data-acc-panel]', it);
+      if (!btn || !panel) return;
+
+      btn.addEventListener('click', () => {
+        const isOpen = btn.getAttribute('aria-expanded') === 'true';
+        closeAll();
+        if (!isOpen) {
